      SUBROUTINE PLTSXZCC     PLOTS SBEND ON A HORIZONTAL PLANECC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DEBUG.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM38C.CIN'      INCLUDE 'ELM38D.CIN'      INCLUDE 'ELM38F.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'OC.CIN'CC     LOCAL VARIABLESC      INTEGER         J, JN, K, LL, NDB      LOGICAL         HTSIDE, DNEXIT      REAL            ANG, CS, CSA, DAH1, DAH2, DAW1, DAW2, DEN,               1                DUH1, DUH2, DUW1, DUW2, GNU, HWIDE      REAL            S, S1, SH, SLESS, SN, SNA, SW      REAL            OMAG(3,3), XMAG(3)      REAL            O1(3,3), OPS(3,3)      DATA            NDB /6/C ---------------------------------------------------------------------CC     CHARACTERIZE ORIENTATION OF MAGNETC      DOTOP = ABS(OPT(2,2)) .GE. 0.001      DOSIDE = ABS(OPT(1,2)) .GE. 0.001      ROLD = OPT(1,2) .NE. 0.0      REVERS = OPT(2,2) .LE. -0.0001      REVERS = REVERS .OR.     1         ABS(OPT(2,2)) .LT. 0.0001 .AND. OPT(1,2) .LT. -0.0001      CWISE = OPT(1,2) .GT. 0.0CC     ENTRANCE FACE COORDINATE SYSTEMC      SN = SIN(AL)      CS = COS(AL)      DO 10 J = 1, 3      DO 10 K = 1, 3      OMAG(J,K) = 0.0   10 CONTINUE      OMAG(1,1) = CS      OMAG(1,3) = - SN      OMAG(2,2) = 1.0      OMAG(3,1) = SN      OMAG(3,3) = CSC      DO 20 J = 1, 3      DO 20 K = 1, 3      S1 = 0.0      DO 15 LL = 1, 3      S1 = S1 + OMAG(J,LL)*O(4,LL,K)   15 CONTINUE      O1(J,K) = S1   20 CONTINUEC      DO 30 J = 1, 3      DO 30 K = 1, 3      OPS(J,K) = O1(J,K)   30 CONTINUEC      DOENT = OPS(3,2) .LE. -0.001      DOEXIT = OPT(3,2) .GE. 0.001      DNEXIT = OPT(3,2) .LE. -0.001      IF (DEBUG) WRITE (NDB,7018) DOENT, DOEXIT, DOTOP, DOSIDE, CWISE,      1                            REVERS 7018 FORMAT (' DOENT = ',L1,2X,'DOEX = ',L1,2X,'DOTOP = ',L1,2X,     1        ' DOSIDE = ',L1,2X,' CWISE = ',L1,2X,'REVERS = ',L1)CC     PROJECTIONS OF MAGNET EDGESC      DUW1 = OPS(1,1)*WIDE/UFLOOR(1)      DUH1 = OPS(2,1)*HIGH/UFLOOR(1)      DAW1 = OPS(1,3)*WIDE/UFLOOR(1)      DAH1 = OPS(2,3)*HIGH/UFLOOR(1)      DUW2 = OPT(1,1)*WIDE/UFLOOR(1)      DUH2 = OPT(2,1)*HIGH/UFLOOR(1)      DAW2 = OPT(1,3)*WIDE/UFLOOR(1)      DAH2 = OPT(2,3)*HIGH/UFLOOR(1)C      IF (DEBUG) WRITE (NDB,7036) DAW1, DUW1 7036 FORMAT (' DAW1 = ',F12.5,3X,'DUW1 = ',F12.5)      IF (DEBUG) WRITE (NDB,7037) DAH2, DUH2 7037 FORMAT (' DAH1 = ',F12.5,3X,'DUH1 = ',F12.5)      IF (DEBUG) WRITE (NDB,7033) DAW2, DUW2 7033 FORMAT (' DAW2 = ',F12.5,3X,'DUW2 = ',F12.5)      IF (DEBUG) WRITE (NDB,7034) DAH2, DUH2 7034 FORMAT (' DAH2 = ',F12.5,3X,'DUH2 = ',F12.5)      IF (DEBUG) WRITE (NDB,7047) QORIG(1), QORIG(2) 7047 FORMAT (' QORIG = ',2F12.5)CC     INTERSECTION OF REFERENCE TRAJECTORY WITH PROJECTEDC     DOWNSTREAM EDGEC      IF (DOEXIT .OR. DNEXIT) THEN        IF (DEBUG) WRITE (NDB,7012) 7012   FORMAT (' VIEW FROM DOWNSTREAM END')        GNU = OPT(1,1)*OPT(2,3) - OPT(2,1)*OPT(1,3)        DEN = OPT(2,1)*OPT(3,3) - OPT(3,1)*OPT(2,3)        IF (ABS(DEN) .LT. 0.00001) THEN          SW = 0.0        ELSE          SW = 0.5*GNU*WIDE/(DEN*UFLOOR(1))          SW = SIGN(SW,OPT(3,3))        ENDIF        GNU = OPT(1,3)*OPT(2,1) - OPT(1,1)*OPT(2,3)        DEN = OPT(3,3)*OPT(1,1) - OPT(1,3)*OPT(3,1)        IF (ABS(DEN) .LT. 0.00001) THEN          SH = 0.0        ELSE          SH = 0.5*GNU*HIGH/(DEN*UFLOOR(1))          SH = SIGN(SH,OPT(3,3))        ENDIF        IF (SW .EQ. 0.0) THEN          SLESS = SH        ELSE IF (SH .EQ. 0.0) THEN          SLESS = SW        ELSE          SLESS = AMIN1(SH,SW)        ENDIF        HTSIDE = SH .NE. 0.0 .AND. SW .NE. 0.0 .AND. SW .LT. SH        HTSIDE = SH .EQ. 0.0 .OR. HTSIDE        IF (DEBUG) WRITE (NDB,7019) HTSIDE 7019   FORMAT (' HTSIDE = ',L2)        IF (DEBUG) WRITE (NDB,7006) SW, SH, SLESS 7006   FORMAT (' SW = ',E15.5,3X,'SH = ',E15.5,3X,'SLESS = ',E15.5)        QPLOT(1) = QORIG(1) + OPT(3,3)*SLESS        QPLOT(2) = QORIG(2) + OPT(3,1)*SLESS        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2) 7009   FORMAT (' QPLOT = ',2F12.5)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2) 7008   FORMAT (8F10.5)      ENDIFCC     IF FACING EXIT, TRACE ABOUT EXIT FACEC      IF (DOEXIT) THEN        IF (REVERS .AND. .NOT. HTSIDE) THEN          IF (DEBUG) WRITE (NDB,7023) 7023     FORMAT (' TRACE ALONG LOWER SIDE')          QPLOT(1) = QORIG(1) + 0.5*DAH2 - 0.5*DAW2          QPLOT(2) = QORIG(2) + 0.5*DUH2 - 0.5*DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIFC        IF ((REVERS .AND. .NOT. HTSIDE)     1      .OR. (CWISE .AND. HTSIDE)) THEN          QPLOT(1) = QORIG(1) - 0.5*DAH2 - 0.5*DAW2          QPLOT(2) = QORIG(2) - 0.5*DUH2 - 0.5*DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIFC        IF (CWISE .OR. .NOT. HTSIDE) THEN          IF (DEBUG) WRITE (NDB,7024) 7024     FORMAT (' TRACE ALONG BOTTOM')          QPLOT(1) = QORIG(1) - 0.5*DAH2 + 0.5*DAW2          QPLOT(2) = QORIG(2) - 0.5*DUH2 + 0.5*DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIFC        IF (DEBUG) WRITE (NDB,7022) 7022   FORMAT (' LOOP AROUND EXIT FACE')        QPLOT(1) = QORIG(1) + 0.5*DAH2 + 0.5*DAW2        QPLOT(2) = QORIG(2) + 0.5*DUH2 + 0.5*DUW2        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) - DAW2        QPLOT(2) = QPLOT(2) - DUW2        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) - DAH2        QPLOT(2) = QPLOT(2) - DUH2        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)C        IF (.NOT. REVERS .OR. (.NOT. CWISE .AND. HTSIDE)) THEN          QPLOT(1) = QPLOT(1) + DAW2          QPLOT(2) = QPLOT(2) + DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          IF (DOTOP .OR. .NOT. CWISE) THEN            QPLOT(1) = QPLOT(1) + DAH2            QPLOT(2) = QPLOT(2) + DUH2C           IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)            WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          ENDIF        ENDIFC        IF (.NOT. CWISE .AND. REVERS .AND. HTSIDE) THEN          QPLOT(1) = QPLOT(1) - DAW2          QPLOT(2) = QPLOT(2) - DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          IF (DOTOP) THEN            QPLOT(1) = QPLOT(1) - DAH2            QPLOT(2) = QPLOT(2) - DUH2            IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)            WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          ENDIF        ENDIF      ENDIFCC     IF NOT FACING EXIT, TRACE APPROPRIATE EXIT EDGESC      IF (.NOT. DOEXIT .AND. DOTOP) THEN        IF (CWISE .AND. (.NOT. REVERS .OR. .NOT. HTSIDE)) THEN          QPLOT(1) = QORIG(1) + 0.5*DAH2 + 0.5*DAW2          QPLOT(2) = QORIG(2) + 0.5*DUH2 + 0.5*DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ELSE IF (CWISE .AND. REVERS .AND. HTSIDE) THEN          QPLOT(1) = QORIG(1) - 0.5*DAH2 + 0.5*DAW2          QPLOT(2) = QORIG(2) - 0.5*DUH2 + 0.5*DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) - DAW2          QPLOT(2) = QPLOT(2) - DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ELSE IF (.NOT. CWISE .AND. REVERS) THEN          QPLOT(1) = QORIG(1) - 0.5*DAH2 - 0.5*DAW2          QPLOT(2) = QORIG(2) - 0.5*DUH2 - 0.5*DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ELSE          QPLOT(1) = QORIG(1) + 0.5*DAH2 - 0.5*DAW2          QPLOT(2) = QORIG(2) + 0.5*DUH2 - 0.5*DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) + DAW2          QPLOT(2) = QPLOT(2) + DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIF      ENDIFCC     IF TOP (OR BOTTOM) NOT VISIBLE, ADVANCE TO NEXT EDGE FOR SIDEC      IF (DNEXIT .AND. .NOT. DOTOP) THEN        IF (CWISE) THEN          QPLOT(1) = QORIG(1) - 0.5*DAH2 + 0.5*DAW2          QPLOT(2) = QORIG(2) - 0.5*DUH2 + 0.5*DUW2        ELSE          QPLOT(1) = QORIG(1) + 0.5*DAH2 - 0.5*DAW2          QPLOT(2) = QORIG(2) + 0.5*DUH2 - 0.5*DUW2        ENDIF        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)      ENDIFCC     VIEW FROM TOPC      IF (DOTOP) THEN        IF (DEBUG) WRITE (NDB,7010) 7010   FORMAT (' VIEW FROM TOP')        IF (.NOT. REVERS) THEN          QREF(1) = QPLOT(1) - 0.5*DAW2          QREF(2) = QPLOT(2) - 0.5*DUW2          HWIDE = 0.5*WIDE        ELSE          QREF(1) = QPLOT(1) + 0.5*DAW2          QREF(2) = QPLOT(2) + 0.5*DUW2          HWIDE = - 0.5*WIDE        ENDIF        IF (DEBUG) WRITE (NDB,7032) (QREF(J), J = 1, 2) 7032   FORMAT (' QREF = ',2F12.5)CC     DOWN ALONG EDGE OF TOPC        IF (DEBUG) WRITE (NDB,7041) 7041   FORMAT (' DOWN ALONG EDGE OF TOP')        DO 150 JN = 1, NANGS        ANG = FLOAT(JN)*DANG        SNA = SIN(ANG)        CSA = COS(ANG)        DO 110 J = 1, 3        DO 110 K = 1, 3        OMAG(J,K) = 0.0  110   CONTINUE        OMAG(1,1) = CSA        OMAG(1,3) = - SNA        OMAG(2,2) = 1.0        OMAG(3,1) = SNA        OMAG(3,3) = CSAC        IF (CSA .GT. 0.5) XMAG(1) = - SNA**2/(H0*(1.0 + CSA))        IF (CSA .LE. 0.5) XMAG(1) = - (1.0 - CSA)/H0        XMAG(2) = 0.0        XMAG(3) = - SNA/H0C        DO 120 J = 1, 3        DO 120 K = 1, 3        S1 = 0.0        DO 115 LL = 1, 3        S1 = S1 + OMAG(J,LL)*O(4,LL,K)  115   CONTINUE        O1(J,K)  =  S1  120   CONTINUEC        DO 130 J = 1, 3        S = 0.0        DO 125 K = 1, 3        S = S + O(4,K,J)*XMAG(K)  125   CONTINUE        XPT(J) = S  130   CONTINUEC        DO 140 J = 1, 3        DO 135 K = 1, 3        OPT(J,K) = O1(J,K)  135   CONTINUE  140   CONTINUE        QPLOT(1) = QREF(1) + (XPT(3) + OPT(1,3)*HWIDE)/UFLOOR(1)        QPLOT(2) = QREF(2) + (XPT(1) + OPT(1,1)*HWIDE)/UFLOOR(1)        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)  150   CONTINUECC     CROSS ENTRANCE FACEC        IF (.NOT. DOENT) THEN          IF (DEBUG) WRITE (NDB,7035) 7035     FORMAT (' CROSS ENTRANCE FACE')          IF (.NOT. REVERS) THEN            QPLOT(1) = QPLOT(1) - DAW1            QPLOT(2) = QPLOT(2) - DUW1          ELSE            QPLOT(1) = QPLOT(1) + DAW1            QPLOT(2) = QPLOT(2) + DUW1          ENDIF          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIFCC     LOOP AROUND ENTRANCE FACEC        IF (DOENT) THEN          IF (DEBUG) WRITE (NDB,7021) 7021     FORMAT (' LOOP AROUND ENTRANCE FACE')          IF (.NOT. REVERS) THEN            QPLOT(1) = QPLOT(1) - DAW1            QPLOT(2) = QPLOT(2) - DUW1            IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)            WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)            QPLOT(1) = QPLOT(1) - DAH1            QPLOT(2) = QPLOT(2) - DUH1            IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)            WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          ENDIF          QPLOT(1) = QPLOT(1) + DAW1          QPLOT(2) = QPLOT(2) + DUW1          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) + DAH1          QPLOT(2) = QPLOT(2) + DUH1          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) - DAW1          QPLOT(2) = QPLOT(2) - DUW1          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          IF (REVERS) THEN            QPLOT(1) = QPLOT(1) - DAH1            QPLOT(2) = QPLOT(2) - DUH1            IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)            WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)            QPLOT(1) = QPLOT(1) + DAW1            QPLOT(2) = QPLOT(2) + DUW1            IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)            WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          ENDIF        ENDIFCC     RETURN ALONG EDGE OF TOPC        IF (DEBUG) WRITE (NDB,7040) 7040   FORMAT (' RETURN ALONG EDGE OF TOP')        DO 200 JN = 1, NANGS        ANG = FLOAT(NANGS - JN)*DANG        SNA = SIN(ANG)        CSA = COS(ANG)        DO 160 J = 1, 3        DO 160 K = 1, 3        OMAG(J,K) = 0.0  160   CONTINUE        OMAG(1,1) = CSA        OMAG(1,3) = - SNA        OMAG(2,2) = 1.0        OMAG(3,1) = SNA        OMAG(3,3) = CSAC        IF (CSA .GT. 0.5) XMAG(1) = - SNA**2/(H0*(1.0 + CSA))        IF (CSA .LE. 0.5) XMAG(1) = - (1.0 - CSA)/H0        XMAG(2) = 0.0        XMAG(3) = - SNA/H0C        DO 170 J = 1, 3        DO 170 K = 1, 3        S1 = 0.0        DO 165 LL = 1, 3        S1 = S1 + OMAG(J,LL)*O(4,LL,K)  165   CONTINUE        O1(J,K)  =  S1  170   CONTINUEC        DO 180 J = 1, 3        S = 0.0        DO 175 K = 1, 3        S = S + O(4,K,J)*XMAG(K)  175   CONTINUE        XPT(J) = S  180   CONTINUEC        DO 190 J = 1, 3        DO 185 K = 1, 3        OPT(J,K) = O1(J,K)  185   CONTINUE  190   CONTINUEC        QPLOT(1) = QREF(1) + (XPT(3) - OPT(1,3)*HWIDE)/UFLOOR(1)        QPLOT(2) = QREF(2) + (XPT(1) - OPT(1,1)*HWIDE)/UFLOOR(1)        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)  200   CONTINUE      ENDIFCC     TRANSITION FROM TOP TO SIDEC      IF (DOSIDE .AND. DOTOP) THEN        IF (DEBUG) WRITE (NDB,7026) 7026   FORMAT (' TRANSITION FROM TOP TO SIDE')        IF (CWISE .AND. .NOT. REVERS) THEN          QPLOT(1) = QPLOT(1) + DAW2          QPLOT(2) = QPLOT(2) + DUW2        ELSE IF (.NOT. CWISE .AND. REVERS) THEN          QPLOT(1) = QPLOT(1) - DAW2          QPLOT(2) = QPLOT(2) - DUW2        ENDIF        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)C        IF (.NOT. REVERS) THEN          QPLOT(1) = QPLOT(1) - DAH2          QPLOT(2) = QPLOT(2) - DUH2        ELSE          QPLOT(1) = QPLOT(1) + DAH2          QPLOT(2) = QPLOT(2) + DUH2        ENDIF        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)      ENDIFCC     VIEW FROM SIDEC      IF (DOSIDE) THEN        IF (CWISE) THEN          QREF(1) = QPLOT(1) - 0.5*DAW2          QREF(2) = QPLOT(2) - 0.5*DUW2          HWIDE = 0.5*WIDE        ELSE          QREF(1) = QPLOT(1) + 0.5*DAW2          QREF(2) = QPLOT(2) + 0.5*DUW2          HWIDE = - 0.5*WIDE        ENDIF        IF (DEBUG) WRITE (NDB,7039) HWIDE 7039   FORMAT (' HWIDE = ',F12.5)        IF (DEBUG) WRITE (NDB,7032) (QREF(J), J = 1, 2)CC     DOWN ALONG EDGE OF SIDEC        IF (DEBUG) WRITE (NDB,7044) 7044   FORMAT (' DOWN ALONG EDGE OF SIDE')        DO 250 JN = 1, NANGS        ANG = FLOAT(JN)*DANG        SNA = SIN(ANG)        CSA = COS(ANG)        DO 210 J = 1, 3        DO 210 K = 1, 3        OMAG(J,K) = 0.0  210   CONTINUE        OMAG(1,1) = CSA        OMAG(1,3) = - SNA        OMAG(2,2) = 1.0        OMAG(3,1) = SNA        OMAG(3,3) = CSAC        IF (CSA .GT. 0.5) XMAG(1) = - SNA**2/(H0*(1.0 + CSA))        IF (CSA .LE. 0.5) XMAG(1) = - (1.0 - CSA)/H0        XMAG(2) = 0.0        XMAG(3) = - SNA/H0C        DO 220 J = 1, 3        DO 220 K = 1, 3        S1 = 0.0        DO 215 LL = 1, 3        S1 = S1 + OMAG(J,LL)*O(4,LL,K)  215   CONTINUE        O1(J,K)  =  S1  220   CONTINUEC        DO 230 J = 1, 3        S = 0.0        DO 225 K = 1, 3        S = S + O(4,K,J)*XMAG(K)  225   CONTINUE        XPT(J) = S  230   CONTINUEC        DO 240 J = 1, 3        DO 235 K = 1, 3        OPT(J,K) = O1(J,K)  235   CONTINUE  240   CONTINUEC        QPLOT(1) = QREF(1) + (XPT(3) + OPT(1,3)*HWIDE)/UFLOOR(1)        QPLOT(2) = QREF(2) + (XPT(1) + OPT(1,1)*HWIDE)/UFLOOR(1)        IF (DEBUG) WRITE (NDB,7038) (QPLOT(J), J = 1, 2),     1             XPT(1), XPT(3), OPT(1,3), OPT(1,1) 7038   FORMAT (' QPLOT = ',2F12.5,3X,'XPT = ',2F12.5,3X,     1          'OPT = ',2F12.5)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)  250   CONTINUECC     CROSS ENTRANCE FACEC        IF (.NOT. DOENT .OR. DOTOP) THEN          IF (.NOT. REVERS) THEN            QPLOT(1) = QPLOT(1) + DAH1            QPLOT(2) = QPLOT(2) + DUH1          ELSE            QPLOT(1) = QPLOT(1) - DAH1            QPLOT(2) = QPLOT(2) - DUH1          ENDIF          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIFCC     LOOP AROUND ENTRANCE FACEC        IF (DOENT .AND. .NOT. DOTOP) THEN          IF (DEBUG) WRITE (NDB,7027) 7027     FORMAT (' LOOP AROUND ENTRANCE FACE')          IF (.NOT. REVERS) THEN            QPLOT(1) = QPLOT(1) + DAH1            QPLOT(2) = QPLOT(2) + DUH1            IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)            WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)            QPLOT(1) = QPLOT(1) - DAW1            QPLOT(2) = QPLOT(2) - DUW1            IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)            WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          ENDIF          QPLOT(1) = QPLOT(1) - DAH1          QPLOT(2) = QPLOT(2) - DUH1          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) + DAW1          QPLOT(2) = QPLOT(2) + DUW1          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) + DAH1          QPLOT(2) = QPLOT(2) + DUH1          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          IF (REVERS) THEN            QPLOT(1) = QPLOT(1) - DAW1            QPLOT(2) = QPLOT(2) - DUW1            IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)            WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)            QPLOT(1) = QPLOT(1) - DAH1            QPLOT(2) = QPLOT(2) - DUH1            IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)            WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          ENDIF        ENDIFCC     RETURN ALONG EDGE OF SIDEC        IF (DEBUG) WRITE (NDB,7045) 7045   FORMAT (' RETURN ALONG EDGE OF SIDE')        IF (.NOT. REVERS) THEN          QREF(1) = QREF(1) + DAH2          QREF(2) = QREF(2) + DUH2        ELSE          QREF(1) = QREF(1) - DAH2          QREF(2) = QREF(2) - DUH2        ENDIF        IF (DEBUG) WRITE (NDB,7032) (QREF(J), J = 1, 2)C        DO 300 JN = 1, NANGS        ANG = FLOAT(NANGS - JN)*DANG        SNA = SIN(ANG)        CSA = COS(ANG)        DO 260 J = 1, 3        DO 260 K = 1, 3        OMAG(J,K) = 0.0  260   CONTINUE        OMAG(1,1) = CSA        OMAG(1,3) = - SNA        OMAG(2,2) = 1.0        OMAG(3,1) = SNA        OMAG(3,3) = CSAC        IF (CSA .GT. 0.5) XMAG(1) = - SNA**2/(H0*(1.0 + CSA))        IF (CSA .LE. 0.5) XMAG(1) = - (1.0 - CSA)/H0        XMAG(2) = 0.0        XMAG(3) = - SNA/H0C        DO 270 J = 1, 3        DO 270 K = 1, 3        S1 = 0.0        DO 265 LL = 1, 3        S1 = S1 + OMAG(J,LL)*O(4,LL,K)  265   CONTINUE        O1(J,K)  =  S1  270   CONTINUEC        DO 280 J = 1, 3        S = 0.0        DO 275 K = 1, 3        S = S + O(4,K,J)*XMAG(K)  275   CONTINUE        XPT(J) = S  280   CONTINUEC        DO 290 J = 1, 3        DO 290 K = 1, 3        OPT(J,K) = O1(J,K)  290   CONTINUEC        QPLOT(1) = QREF(1) + (XPT(3) + OPT(1,3)*HWIDE)/UFLOOR(1)        QPLOT(2) = QREF(2) + (XPT(1) + OPT(1,1)*HWIDE)/UFLOOR(1)        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)  300   CONTINUE      ENDIFCC     LOOP AROUND EXIT FACEC      IF (DOEXIT) THEN        IF (DEBUG) WRITE (NDB,7020) 7020   FORMAT (' LOOP AROUND EXIT FACE')        IF (CWISE .AND. .NOT. REVERS) THEN          QPLOT(1) = QPLOT(1) - DAW2          QPLOT(2) = QPLOT(2) - DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIFC        IF (.NOT. HTSIDE .AND. .NOT. REVERS) THEN          QPLOT(1) = QPLOT(1) - DAH2          QPLOT(2) = QPLOT(2) - DUH2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIFC        IF (.NOT. CWISE) THEN          QPLOT(1) = QPLOT(1) + DAW2          QPLOT(2) = QPLOT(2) + DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIFC        IF (REVERS .AND. ((CWISE .AND. DOTOP)     1      .OR. .NOT. HTSIDE)) THEN          QPLOT(1) = QPLOT(1) + DAH2          QPLOT(2) = QPLOT(2) + DUH2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIFC        IF (CWISE .AND. REVERS .AND. DOSIDE) THEN          QPLOT(1) = QPLOT(1) - DAW2          QPLOT(2) = QPLOT(2) - DUW2          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIF      ENDIFCC     REFERENCE TRAJECTORY AT EXIT FACEC      IF (DOEXIT .OR. DNEXIT) THEN        IF (DEBUG) WRITE (NDB,7046) 7046   FORMAT (' REFERENCE TRAJECTORY AT EXIT FACE')        QPLOT(1) = QORIG(1) + OPT(3,3)*SLESS        QPLOT(2) = QORIG(2) + OPT(3,1)*SLESS        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)      ENDIF      QPLOT(1) = QORIG(1)      QPLOT(2) = QORIG(2)      IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)      WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)      RETURN      END